#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/basic_controls.hpp"
#include "gui_forms/controls/range_control/range_control_values/range_control_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RangeControl's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/range_control.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The current value (Value), within minimum and maximum; a view onto the range's value. Outside them throws std::out_of_range, a non-finite value std::invalid_argument; a bound Value may refuse it. A change raises value_changed.
template <typename Declaring>
struct RangeControlValueCapability {
    PropertyView<double, RangeControlValueCapability<Declaring>> value;

    static void assign(RangeControlValueCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.value), std::move(incoming));
    }

    static double read(const RangeControlValueCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.value);
        return current;
    }
};

// The lower bound (Minimum); a view onto the range: a write is set_range(incoming, maximum), so it must stay below the maximum.
template <typename Declaring>
struct RangeControlMinimumCapability {
    PropertyView<double, RangeControlMinimumCapability<Declaring>> minimum;

    static void assign(RangeControlMinimumCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.minimum), std::move(incoming));
    }

    static double read(const RangeControlMinimumCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.minimum);
        return current;
    }
};

// The upper bound (Maximum); a view onto the range: a write is set_range(minimum, incoming), so it must stay above the minimum.
template <typename Declaring>
struct RangeControlMaximumCapability {
    PropertyView<double, RangeControlMaximumCapability<Declaring>> maximum;

    static void assign(RangeControlMaximumCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.maximum), std::move(incoming));
    }

    static double read(const RangeControlMaximumCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.maximum);
        return current;
    }
};

// How far an arrow key or button moves the value (SmallChange); positive and finite, else std::invalid_argument.
template <typename Declaring>
struct RangeControlSmallChangeCapability {
    PropertyCell<double, RangeControlSmallChangeCapability<Declaring>> small_change{1.0};

    static void assign(RangeControlSmallChangeCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.small_change), incoming);
        if (!capability.small_change.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.small_change));
    }
};

// How far a track click or Page Up/Down moves the value (LargeChange); positive and finite, else std::invalid_argument.
template <typename Declaring>
struct RangeControlLargeChangeCapability {
    PropertyCell<double, RangeControlLargeChangeCapability<Declaring>> large_change{10.0};

    static void assign(RangeControlLargeChangeCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.large_change), incoming);
        if (!capability.large_change.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.large_change));
    }
};

// Horizontal or vertical (Orientation).
template <typename Declaring>
struct RangeControlOrientationCapability {
    PropertyCell<Orientation, RangeControlOrientationCapability<Declaring>> orientation{Orientation::horizontal};

    static void assign(RangeControlOrientationCapability& capability, Orientation incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.orientation), incoming);
        if (!capability.orientation.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.orientation));
    }
};

// Every RangeControl capability, in the order the declaring class takes them.
template <typename Declaring>
struct RangeControlCapabilities : public RangeControlValueCapability<Declaring>,
                                  public RangeControlMinimumCapability<Declaring>,
                                  public RangeControlMaximumCapability<Declaring>,
                                  public RangeControlSmallChangeCapability<Declaring>,
                                  public RangeControlLargeChangeCapability<Declaring>,
                                  public RangeControlOrientationCapability<Declaring> {};

} // namespace gui_forms
